31	MapView::MapView(
32	    uint32_t width,
33	    uint32_t height,
34	    lv_obj_t* parent,
35	    EventListener* listener,
36	    void* userData)
37	    : _tileView(width, height)
38	    , _mapConv(true, 16)
39	    , _curGeoCoord { 0 }
40	    , _curLevel(0)
41	    , _config { 0 }
42	    , _viewCont(nullptr)
43	    , _timerMapReset(nullptr)
44	    , _lastShortClickTime(0)
45	    , _animBusy(false)
46	    , _animStart { 0 }
47	    , _animEnd { 0 }
48	    , _tileSrcEanble(true)
49	    , _listener(listener)
50	    , _userData(userData)
51	{
52	    _tileView.setFocusPos(0, 0);
53	
54	    lv_obj_t* viewCont = lv_obj_create(parent);
55	    _viewCont = viewCont;
56	    lv_obj_remove_style_all(viewCont);
57	    lv_obj_set_size(viewCont, width, height);
58	
59	    /* scoll auto load map view */
60	    lv_obj_add_event(
61	        viewCont, [](lv_event_t* e) {
62	            if (!lv_indev_get_act()) {
63	                return;
64	            }
65	
66	            auto self = (MapView*)lv_event_get_user_data(e);
67	            self->onMoving();
68	
69	            /* update focus point */
70	            auto focus = self->getFocus();
71	            self->setFocusRow(focus.x, focus.y);
72	        },
73	        LV_EVENT_SCROLL, this);
74	
75	    /* double click to zoom up */
76	    lv_obj_add_event(
77	        viewCont, [](lv_event_t* e) {
78	            auto self = (MapView*)lv_event_get_user_data(e);
79	
80	            /* not scrollable */
81	            if (!lv_obj_has_flag(self->_viewCont, LV_OBJ_FLAG_SCROLLABLE)) {
82	                return;
83	            }
84	
85	            /* double click */
86	            if (lv_tick_elaps(self->_lastShortClickTime) < 300) {
87	                if (self->setLevel(self->_curLevel + 1)) {
88	                    self->sendEvent(EVENT_ID::LEVEL_CHANGED, &self->_curLevel);
89	                }
90	
91	                self->onMoving();
92	
93	                lv_point_t p;
94	                lv_indev_get_point(lv_indev_get_act(), &p);
95	
96	                lv_obj_t* cont = lv_obj_get_child(self->_viewCont, 0);
97	                lv_area_t area;
98	                lv_obj_get_coords(cont, &area);
99	
100	                int32_t x = p.x - area.x1;
101	                int32_t y = p.y - area.y1;
102	
103	                auto oriPos = self->_tileView.getTilePos(0);
104	                self->setFocus(oriPos.x + x, oriPos.y + y, LV_ANIM_ON);
105	            }
106	
107	            self->_lastShortClickTime = lv_tick_get();
108	        },
109	        LV_EVENT_SHORT_CLICKED, this);
110	
111	    /* coord change move map */
112	    subscribe(MSG_ID::GEO_COORD_UPDATE, viewCont, [](lv_event_t* e) {
113	        auto self = (MapView*)lv_event_get_user_data(e);
114	        auto msg = lv_event_get_msg(e);
115	
116	        if (self->msgID(MSG_ID::GEO_COORD_UPDATE) != lv_msg_get_id(msg)) {
117	            return;
118	        }
119	        auto obj = lv_event_get_target_obj(e);
120	
121	        /* not move when edit */
122	        if (lv_obj_has_state(obj, MAP_MOVED_STATE)) {
123	            return;
124	        }
125	
126	        auto geoCoord = (const GeoCoord_t*)lv_msg_get_payload(msg);
127	        self->setFocus(geoCoord);
128	    });
129	
130	    subscribe(MSG_ID::MOVE_RESET, viewCont, [](lv_event_t* e) {
131	        auto self = (MapView*)lv_event_get_user_data(e);
132	        auto msg = lv_event_get_msg(e);
133	
134	        if (self->msgID(MSG_ID::MOVE_RESET) != lv_msg_get_id(msg)) {
135	            return;
136	        }
137	
138	        auto obj = lv_event_get_current_target_obj(e);
139	        lv_obj_clear_state(obj, MAP_MOVED_STATE);
140	        self->setFocus(&self->_curGeoCoord, true);
141	    });
142	
143	    /* map cont */
144	    {
145	        lv_obj_t* cont = lv_obj_create(viewCont);
146	        lv_obj_remove_style_all(cont);
147	        lv_obj_clear_flag(cont, LV_OBJ_FLAG_CLICKABLE);
148	
149	        TileView::Rect_t rect = _tileView.getTileRect();
150	        lv_obj_set_size(cont, rect.width, rect.height);
151	
152	        /* map img */
153	        uint32_t tileNum = _tileView.getTileNum();
154	        for (uint32_t i = 0; i < tileNum; i++) {
155	            lv_obj_t* img = lv_img_create(cont);
156	            lv_obj_remove_style_all(img);
157	        }
158	    }
159	
160	    /* map reset timer */
161	    _timerMapReset = lv_timer_create([](lv_timer_t* timer) {
162	        auto self = (MapView*)lv_timer_get_user_data(timer);
163	        self->publish(MSG_ID::MOVE_RESET);
164	        self->sendEvent(EVENT_ID::MOVE_RESET);
165	        lv_timer_pause(timer);
166	    },
167	        0, this);
168	    lv_timer_pause(_timerMapReset);
169	}
