185	void MapView::setFocus(int32_t x, int32_t y, bool animEn)
186	{
187	    if (animEn) {
188	        lv_anim_t a;
189	        lv_anim_init(&a);
190	        lv_anim_set_var(&a, this);
191	        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
192	        lv_anim_set_time(&a, 300);
193	        lv_anim_set_values(&a, 0, 1000);
194	        lv_anim_set_ready_cb(&a, [](lv_anim_t* anim) {
195	            auto self = (MapView*)anim->var;
196	            self->cancelAnim();
197	        });
198	
199	        lv_anim_set_exec_cb(&a, [](void* var, int32_t v) {
200	            auto self = (MapView*)var;
201	            int32_t fx = lv_map(v, 0, 1000, self->_animStart.x, self->_animEnd.x);
202	            int32_t fy = lv_map(v, 0, 1000, self->_animStart.y, self->_animEnd.y);
203	            self->setFocusRow(fx, fy);
204	        });
205	
206	        _animStart = getFocus();
207	        _animEnd.x = x;
208	        _animEnd.y = y;
209	        _animBusy = true;
210	        lv_anim_start(&a);
211	        return;
212	    }
213	
214	    if (_animBusy) {
215	        return;
216	    }
217	
218	    setFocusRow(x, y);
219	}
