367	void MapView::setFocusRow(int32_t x, int32_t y)
368	{
369	    _tileView.setFocusPos(x, y);
370	    TileView::Point offset = _tileView.getTileRectOffset();
371	    lv_obj_scroll_to(_viewCont, offset.x, offset.y, LV_ANIM_OFF);
372	
373	    /* map reload check */
374	    if (!isTileRectChanged()) {
375	        return;
376	    }
377	
378	    /* tile src */
379	    if (_tileSrcEanble) {
380	        lv_obj_t* cont = lv_obj_get_child(_viewCont, 0);
381	        uint32_t tileNum = _tileView.getTileNum();
382	        lv_disp_t* disp = lv_obj_get_disp(cont);
383	        lv_disp_enable_invalidation(disp, false);
384	        for (uint32_t i = 0; i < tileNum; i++) {
385	            TileView::Point_t pos = _tileView.getTilePos(i);
386	            lv_obj_t* img = lv_obj_get_child(cont, i);
387	
388	            char mapPath[32];
389	            _mapConv.getPath(mapPath, sizeof(mapPath), pos.x, pos.y);
390	
391	            char realPath[64];
392	            lv_snprintf(realPath, sizeof(realPath),
393	                "%s%s.%s", _config.path, mapPath, _config.ext);
394	
395	            auto imgPos = _tileView.getOffset(&pos);
396	            lv_obj_set_pos(img, imgPos.x, imgPos.y);
397	            lv_img_set_src(img, realPath);
398	        }
399	        lv_disp_enable_invalidation(disp, true);
400	
401	        /* merge invalid area */
402	        lv_obj_invalidate(_viewCont);
403	    }
404	
405	    /* update tile view rect */
406	    _curTileRect = _tileView.getTileRect();
407	    LV_LOG_INFO("tile rect: %" LV_PRId32 ", %" LV_PRId32 ", %" LV_PRId32 ", %" LV_PRId32,
408	        _curTileRect.x, _curTileRect.y, _curTileRect.width, _curTileRect.height);
409	
410	    publish(MSG_ID::TILE_RECT_CHANGED, &_curTileRect);
411	    sendEvent(EVENT_ID::TILE_RECT_CHANGED, &_curTileRect);
412	}
