435	bool MapView::arrowCheck(lv_obj_t* img)
436	{
437	    auto mapCoord = _mapConv.getCoordinate(_curGeoCoord.longitude, _curGeoCoord.latitude);
438	    auto imgPos = _tileView.getOffset((TileView::Point_t*)&mapCoord);
439	
440	    if (imgPos.x < 0 || imgPos.y < 0
441	        || imgPos.x > _curTileRect.width || imgPos.y > _curTileRect.height) {
442	        lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);
443	        return false;
444	    }
445	
446	    lv_obj_set_pos(img, imgPos.x, imgPos.y);
447	    lv_obj_clear_flag(img, LV_OBJ_FLAG_HIDDEN);
448	    return true;
449	}
