39	void TileView::setFocusPos(int32_t x, int32_t y)
40	{
41	    _pointFocus.x = x;
42	    _pointFocus.y = y;
43	
44	    const int32_t viewHalfWidth = _viewWidth / 2;
45	    const int32_t viewHalfHeight = _viewHeight / 2;
46	    const uint32_t tileSize = _tileSize;
47	
48	    _pointView[0].x = x - viewHalfWidth;
49	    _pointView[0].y = y - viewHalfHeight;
50	    _pointView[1].x = x + viewHalfWidth;
51	    _pointView[1].y = y - viewHalfHeight;
52	    _pointView[2].x = x - viewHalfWidth;
53	    _pointView[2].y = y + viewHalfHeight;
54	    _pointView[3].x = x + viewHalfWidth;
55	    _pointView[3].y = y + viewHalfHeight;
56	
57	    const int32_t tileContWidth = (_viewWidth / tileSize + 2) * tileSize;
58	    const int32_t tileContHeight = (_viewHeight / tileSize + 2) * tileSize;
59	
60	    _pointTileCont[0].x = roundTile(_pointView[0].x, false);
61	    _pointTileCont[0].y = roundTile(_pointView[0].y, false);
62	    _pointTileCont[1].x = _pointTileCont[0].x + tileContWidth;
63	    _pointTileCont[1].y = _pointTileCont[0].y;
64	    _pointTileCont[2].x = _pointTileCont[0].x;
65	    _pointTileCont[2].y = _pointTileCont[0].y + tileContHeight;
66	    _pointTileCont[3].x = _pointTileCont[0].x + tileContWidth;
67	    _pointTileCont[3].y = _pointTileCont[0].y + tileContHeight;
68	}
