105	TileView::Point_t TileView::getTilePos(uint32_t index)
106	{
107	    Point_t pos;
108	    int32_t width = _pointTileCont[1].x - _pointTileCont[0].x;
109	    int32_t widthIndexMax = width / _tileSize;
110	    pos.x = _pointTileCont[0].x + _tileSize * (index % widthIndexMax);
111	    pos.y = _pointTileCont[0].y + _tileSize * (index / widthIndexMax);
112	    return pos;
113	}
