121	int32_t TileView::roundTile(int32_t x, bool up)
122	{
123	    int32_t r = x % _tileSize;
124	
125	    if (r == 0) {
126	        return x;
127	    }
128	
129	    int32_t ret = x - r;
130	
131	    if (up) {
132	        ret += _tileSize;
133	    }
134	
135	    return ret;
136	}
