138	TileView::Point_t TileView::getOffset(const Point_t* point)
139	{
140	    Point_t offset;
141	    offset.x = point->x - _pointTileCont[0].x;
142	    offset.y = point->y - _pointTileCont[0].y;
143	    return offset;
144	}
