95	MapConv::Tile_t MapConv::posToTile(int32_t x, int32_t y)
96	{
97	    Tile_t mapTile;
98	    mapTile.tileX = x / _tileSize;
99	    mapTile.tileY = y / _tileSize;
100	    mapTile.subX = x % _tileSize;
101	    mapTile.subY = y % _tileSize;
102	    return mapTile;
103	}
104	
105	MapConv::Point_t MapConv::convertPoint(int32_t x, int32_t y, int level)
106	{
107	    Point_t point;
108	
109	    int diff = level - _level;
110	
111	    if (diff >= 0) {
112	        point.x = x >> diff;
113	        point.y = y >> diff;
114	    } else {
115	        point.x = x << -diff;
116	        point.y = y << -diff;
117	    }
118	
119	    return point;
120	}
