99	void LiveMapView::mapViewCreate(lv_obj_t* par)
100	{
101	    /* update view size */
102	    lv_obj_update_layout(par);
103	    lv_coord_t view_w = lv_obj_get_width(par);
104	    lv_coord_t view_h = lv_obj_get_height(par);
105	
106	    /* map viewer */
107	    _mapView = new MapView(view_w, view_h, par, onMapViewEvent, this);
108	    _mapView->setScrollEanble(false);
109	    _mapView->setTileSrcEanble(false);
110	    lv_obj_t* viewCont = _mapView->getViewCont();
111	
112	    /* geo coord update */
113	    subscribe(MSG_ID::GEO_COORD_UPDATE, viewCont, [](lv_event_t* e) {
114	        auto msg = lv_event_get_msg(e);
115	        auto self = (LiveMapView*)lv_event_get_user_data(e);
116	
117	        if (self->msgID(MSG_ID::GEO_COORD_UPDATE) != lv_msg_get_id(msg)) {
118	            return;
119	        }
120	
121	        auto geoCoord = (const MapView::GeoCoord_t*)lv_msg_get_payload(msg);
122	        self->_mapView->setGeoCoord(geoCoord);
123	    });
124	
125	    /* set map config */
126	    subscribe(MSG_ID::MAP_CONFIG_UPDATE, viewCont, [](lv_event_t* e) {
127	        auto msg = lv_event_get_msg(e);
128	        auto self = (LiveMapView*)lv_event_get_user_data(e);
129	
