1585	static void view_canvas(const vmap_view_t * view, vmap_canvas_t * canvas,
1586	    bool clip_dirty)
1587	{
1588	    uint8_t i;
1589	
1590	    canvas->buf = (uint16_t *)view->cbuf;
1591	    canvas->w = view->w;
1592	    canvas->h = view->h;
1593	    canvas->stride = view->stride;
1594	    vmap_render_clip_reset(canvas);
1595	    if (!clip_dirty) {
1596	        return;
1597	    }
1598	    for (i = 0; i < view->pump_dirty_n; i++) {
1599	        vmap_render_clip_add(canvas,
1600	            view->pump_dirty_x1[i], view->pump_dirty_y1[i],
1601	            view->pump_dirty_x2[i], view->pump_dirty_y2[i]);
1602	    }
1603	}
1604	
1605	static void pump_dirty_add(vmap_view_t * view, int32_t x1, int32_t y1,
1606	    int32_t x2, int32_t y2)
1607	{
1608	    uint8_t i;
1609	
1610	    if (!view || x1 >= x2 || y1 >= y2) {
1611	        return;
1612	    }
1613	
1614	    if (x1 < 0) {
1615	        x1 = 0;
1616	    }
1617	    if (y1 < 0) {
1618	        y1 = 0;
1619	    }
1620	    if (x2 > view->w) {
1621	        x2 = view->w;
1622	    }
1623	    if (y2 > view->h) {
1624	        y2 = view->h;
1625	    }
1626	    if (x1 >= x2 || y1 >= y2 || view->pump_dirty_n >= VMAP_RENDER_DIRTY_MAX) {
1627	        return;
1628	    }
1629	
1630	    i = view->pump_dirty_n;
1631	    view->pump_dirty_x1[i] = x1;
1632	    view->pump_dirty_y1[i] = y1;
1633	    view->pump_dirty_x2[i] = x2;
1634	    view->pump_dirty_y2[i] = y2;
1635	    view->pump_dirty_n++;
1636	}
1637	
1638	static void pump_dirty_from_scroll(vmap_view_t * view, int32_t sx, int32_t sy)
1639	{
1640	    const int32_t pad = (int32_t)VMAP_RENDER_DIRTY_PAD;
1641	
1642	    view->pump_dirty_n = 0;
1643	    if (sx > 0) {
1644	        pump_dirty_add(view, view->w - sx - pad, 0, view->w, view->h);
1645	    } else if (sx < 0) {
1646	        pump_dirty_add(view, 0, 0, -sx + pad, view->h);
1647	    }
1648	    if (sy > 0) {
1649	        pump_dirty_add(view, 0, view->h - sy - pad, view->w, view->h);
1650	    } else if (sy < 0) {
1651	        pump_dirty_add(view, 0, 0, view->w, -sy + pad);
1652	    }
1653	}
1654	
1655	static bool pump_rects_overlap(int32_t ax1, int32_t ay1, int32_t ax2, int32_t ay2,
1656	    int32_t bx1, int32_t by1, int32_t bx2, int32_t by2)
1657	{
1658	    return ax1 < bx2 && ax2 > bx1 && ay1 < by2 && ay2 > by1;
1659	}
1660	
1661	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
1662	{
1663	    const int32_t tile_size = 256;
1664	    int32_t x1;
1665	    int32_t y1;
1666	    int32_t x2;
1667	    int32_t y2;
1668	    uint8_t i;
1669	
1670	    if (!view || view->pump_dirty_n == 0) {
1671	        return true;
1672	    }
1673	
1674	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
1675	        + view->w / 2.0);
1676	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
1677	        + view->h / 2.0);
1678	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
1679	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
1680	
1681	    for (i = 0; i < view->pump_dirty_n; i++) {
1682	        if (pump_rects_overlap(x1, y1, x2, y2,
1683	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
1684	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
1685	            return true;
1686	        }
1687	    }
1688	    return false;
1689	}
1690	
1691	static bool pump_advance(vmap_view_t * view)
1692	{
1693	    view->pump_ty--;
1694	    if (view->pump_ty < view->pump_ty_min) {
1695	        view->pump_tx--;
1696	        view->pump_ty = view->pump_ty_max;
1697	    }
1698	    return view->pump_tx >= view->pump_tx_min;
1699	}
