1701	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear)
1702	{
1703	    vmap_canvas_t canvas;
1704	    const double origin_lon = reset_view ? view->lon : view->render_lon;
1705	    const double origin_lat = reset_view ? view->lat : view->render_lat;
1706	    int32_t sx;
1707	    int32_t sy;
1708	    bool scrolled = false;
1709	
1710	    /* fopen/.vpk index belongs on the first pump tick, not GNSS/REC/set_view. */
1711	
1712	    vmap_perf_frame_begin();
1713	    VMAP_PERF_T0();
1714	    dvfs_map_busy(true);
1715	    view->pump_dirty_n = 0;
1716	    sx = (view->last_pan_px == INT32_MIN) ? (int32_t)lround(view->pan_dx)
1717	                                         : view->last_pan_px;
1718	    sy = (view->last_pan_py == INT32_MIN) ? (int32_t)lround(view->pan_dy)
1719	                                         : view->last_pan_py;
1720	
1721	    if (reset_view) {
1722	        /*
1723	         * A hidden page can jump much farther than the last on-screen pan.
1724	         * Derive the pixel migration from the two geographic origins instead
1725	         * of trusting last_pan_px.  Otherwise a 1 km jump with a 14 px old pan
1726	         * scrolls only 14 px, then marks the whole interior as the new origin.
1727	         */
1728	        if (!force_clear && view->render_rev > 0
1729	            && view->paint_zoom == view->zoom
1730	            && view->paint_scale == view->scale) {
1731	            int old_x = 0;
1732	            int old_y = 0;
1733	            int new_x = 0;
1734	            int new_y = 0;
1735	
1736	            vmap_latlong_to_pixel(view->render_lat, view->render_lon,
1737	                view->zoom, &old_x, &old_y);
1738	            vmap_latlong_to_pixel(origin_lat, origin_lon,
1739	                view->zoom, &new_x, &new_y);
1740	            sx = (int32_t)lround((new_x - old_x) * view->scale);
1741	            sy = (int32_t)lround((new_y - old_y) * view->scale);
1742	        }
1743	
1744	        bool can_scroll = !force_clear && view->render_rev > 0
1745	            && view->paint_zoom == view->zoom
1746	            && view->paint_scale == view->scale
1747	            && (sx != 0 || sy != 0)
1748	            && sx > -view->w && sx < view->w
1749	            && sy > -view->h && sy < view->h;
1750	
1751	        view->render_lon = origin_lon;
1752	        view->render_lat = origin_lat;
1753	        view_canvas(view, &canvas, false);
1754	        if (can_scroll) {
1755	            {
1756	                VMAP_PERF_T0S();
1757	                vmap_render_scroll(&canvas, sx, sy, vmap_style_bg565());
1758	                pump_dirty_from_scroll(view, sx, sy);
1759	                VMAP_PERF_T1S(scroll);
1760	            }
1761	            {
1762	                VMAP_PERF_T0S();
1763	                vmap_label_retained_scroll(&view->label_col, sx, sy,
1764	                    VMAP_RENDER_DIRTY_MAX, &view->pump_dirty_n,
1765	                    view->pump_dirty_x1, view->pump_dirty_y1,
1766	                    view->pump_dirty_x2, view->pump_dirty_y2);
1767	                VMAP_PERF_T1S(lscroll);
1768	            }
1769	            scrolled = true;
1770	            {
1771	                VMAP_PERF_T0S();
1772	                lv_obj_invalidate(view->canvas);
1773	                VMAP_PERF_T1S(inval);
1774	            }
1775	        } else {
1776	            VMAP_PERF_T0S();
1777	            vmap_render_clear(&canvas, vmap_style_bg565());
1778	            vmap_label_retained_reset(&view->label_col);
1779	            VMAP_PERF_T1S(scroll);  /* 清屏路径复用同一格 */
1780	        }
1781	
1782	        view->pan_dx = 0.0;
1783	        view->pan_dy = 0.0;
1784	        view->last_pan_px = INT32_MIN;
1785	        view->last_pan_py = INT32_MIN;
1786	        vmap_view_apply_canvas_pos(view, 0.0, 0.0);
1787	    } else {
1788	        /* keep-pan redraw repaints every base tile, erasing all baked labels. */
1789	        vmap_label_retained_reset(&view->label_col);
1790	    }
1791	
1792	    vmap_label_collector_reset(&view->label_col);
1793	    view->label_col.clip_n = 0;
1794	    vmap_label_collector_set_focus(&view->label_col,
1795	        view->w / 2 + (int32_t)lround(view->pan_dx),
1796	        view->h / 2 + (int32_t)lround(view->pan_dy));
1797	
1798	    vmap_latlong_to_pixel(origin_lat, origin_lon, view->zoom,
1799	        &view->pump_cx, &view->pump_cy);
1800	    tile_range(view->pump_cx, view->pump_cy, view->w, view->h, view->scale, 1,
1801	        &view->pump_tx_min, &view->pump_ty_min,
1802	        &view->pump_tx_max, &view->pump_ty_max);
1803	    view->pump_tx = view->pump_tx_max;
1804	    view->pump_ty = view->pump_ty_max;
1805	    view->pump_phase = 1;
1806	    view->pump_need_region = 1;
1807	
1808	    if (scrolled) {
1809	        syslog(LOG_INFO,
1810	            "[map] rebase scroll=%d,%d dirty=%u labels=%d z=%d",
1811	            (int)sx, (int)sy, (unsigned)view->pump_dirty_n,
1812	            (int)view->label_col.retained_count, view->zoom);
1813	    }
1814	    VMAP_PERF_T1(begin);
1815	}
1816	
1817	static bool render_next_tile(vmap_view_t * view)
1818	{
1819	    const int32_t tile_size = 256;
1820	    const double scale = view->scale;
1821	    vmap_canvas_t canvas;
1822	    vmap_tile_t tile;
1823	    float base_x;
1824	    float base_y;
1825	    int32_t tx;
1826	    int32_t ty;
1827	    int32_t ix1;
1828	    int32_t iy1;
1829	    int32_t ix2;
1830	    int32_t iy2;
1831	
1832	    if (view->pump_need_region) {
1833	        VMAP_PERF_T0();
1834	        view->pump_need_region = 0;
1835	        if (view->cache) {
1836	            myvendor_watchdog_ui_beat();
1837	            myvendor_watchdog_busy_pump();
1838	            vmap_tile_cache_ensure_region(view->cache,
1839	                view->render_lon, view->render_lat);
1840	            myvendor_watchdog_ui_beat();
1841	        }
1842	        VMAP_PERF_T1(warm);
1843	        return true;
1844	    }
1845	
1846	    while (view->pump_tx >= view->pump_tx_min) {
1847	        tx = view->pump_tx;
1848	        ty = view->pump_ty;
1849	
1850	        if (!pump_tile_dirty(view, tx, ty)) {
1851	            VMAP_PERF_T0();
1852	            if (view->font
1853	                && vmap_tile_cache_cached(view->cache, view->zoom, (int)tx, (int)ty)
1854	                && vmap_tile_cache_get(view->cache, view->zoom, (int)tx, (int)ty,
1855	                    &tile)) {
1856	                base_x = (float)((tx * tile_size - view->pump_cx) * scale
1857	                    + view->w / 2.0);
1858	                base_y = (float)((ty * tile_size - view->pump_cy) * scale
1859	                    + view->h / 2.0);
1860	                vmap_label_collector_add_tile(&view->label_col, &tile,
1861	                    base_x, base_y, (float)scale);
1862	            }
1863	            VMAP_PERF_T1(meta);
1864	            if (!pump_advance(view)) {
1865	                return false;
1866	            }
1867	            continue;
1868	        }
1869	
1870	        if (!vmap_tile_cache_cached(view->cache, view->zoom, (int)tx, (int)ty)) {
1871	            bool warmed;
1872	
1873	            VMAP_PERF_T0();
1874	            warmed = vmap_tile_cache_warm(view->cache, view->zoom,
1875	                    (int)tx, (int)ty);
1876	            VMAP_PERF_T1(warm);
1877	            if (!warmed) {
1878	                /* 邻格 heap 暂时放不下：跳过，继续画已在 PSRAM 的瓦片。 */
1879	                if (!pump_advance(view)) {
1880	                    return false;
1881	                }
1882	                continue;
1883	            }
1884	            VMAP_PERF_N(n_warms);
1885	            return true;
1886	        }
1887	
1888	        view_canvas(view, &canvas, true);
1889	        base_x = (float)((tx * tile_size - view->pump_cx) * scale
1890	            + view->w / 2.0);
1891	        base_y = (float)((ty * tile_size - view->pump_cy) * scale
1892	            + view->h / 2.0);
1893	
1894	        if (vmap_tile_cache_get(view->cache, view->zoom, (int)tx, (int)ty,
1895	                &tile)) {
1896	            uint32_t st = 0u;
1897	            uint32_t by = 0u;
1898	
1899	            VMAP_PERF_T0();
1900	            vmap_render_stat_reset();
1901	            vmap_render_draw_tile(&canvas, &tile, base_x, base_y, (float)scale,
1902	                view->scratch, VMAP_SCRATCH_CAP);
1903	            VMAP_PERF_T1(tile);
1904	            VMAP_PERF_N(n_tiles);
1905	            vmap_render_stat_get(&st, &by);
1906	            s_pf_stores += st;
1907	            s_pf_bytes += by;
1908	            if (view->font) {
1909	                vmap_label_collector_add_tile(&view->label_col, &tile,
1910	                    base_x, base_y, (float)scale);
1911	            }
1912	
1913	            ix1 = (int32_t)floor((double)base_x);
1914	            iy1 = (int32_t)floor((double)base_y);
1915	            ix2 = (int32_t)ceil((double)base_x + 256.0 * scale);
1916	            iy2 = (int32_t)ceil((double)base_y + 256.0 * scale);
1917	            if (view->pump_dirty_n == 0) {
1918	                vmap_view_invalidate_canvas_area(view, ix1, iy1, ix2, iy2);
1919	            } else {
1920	                uint8_t di;
1921	
1922	                for (di = 0; di < view->pump_dirty_n; di++) {
1923	                    int32_t vx1 = ix1 > view->pump_dirty_x1[di]
1924	                        ? ix1 : view->pump_dirty_x1[di];
1925	                    int32_t vy1 = iy1 > view->pump_dirty_y1[di]
1926	                        ? iy1 : view->pump_dirty_y1[di];
1927	                    int32_t vx2 = ix2 < (view->pump_dirty_x2[di] - 1)
1928	                        ? ix2 : (view->pump_dirty_x2[di] - 1);
1929	                    int32_t vy2 = iy2 < (view->pump_dirty_y2[di] - 1)
1930	                        ? iy2 : (view->pump_dirty_y2[di] - 1);
1931	
1932	                    if (vx1 <= vx2 && vy1 <= vy2) {
1933	                        vmap_view_invalidate_canvas_area(view, vx1, vy1, vx2, vy2);
1934	                    }
1935	                }
1936	            }
1937	        }
1938	
1939	        if (!pump_advance(view)) {
1940	            return false;
1941	        }
1942	        return true;
1943	    }
1944	
1945	    return false;
1946	}
