1948	/*
1949	 * Canvas stack, bottom → top:
1950	 *   map tiles (already in buffer) → nav → labels → REC line → REC numbers.
1951	 * clip_dirty: follow-rebase only restamps the new edge, so interior ink is not
1952	 * redrawn fat. Labels use the same dirty rects.
1953	 */
1954	static void stamp_overlays(vmap_view_t * view, bool labels)
1955	{
1956	    vmap_canvas_t canvas;
1957	    lv_area_t label_drawn;
1958	    bool labels_drawn = false;
1959	
1960	    if (!view || !view->canvas || !view->cbuf) {
1961	        return;
1962	    }
1963	
1964	    view_canvas(view, &canvas, true);
1965	
1966	#if VMAP_ROUTE_ENABLE
1967	    if (view->route) {
1968	        VMAP_PERF_T0();
1969	        vmap_route_paint_to_canvas(view->route, &canvas, view);
1970	        VMAP_PERF_T1P(VMAP_PERF_NAV_SLOT());
1971	    }
1972	#endif
1973	
1974	    if (labels && view->font && view->label_col.count > 0) {
1975	        VMAP_PERF_T0();
1976	        labels_drawn = vmap_label_paint_to_canvas(
1977	            view->canvas, &view->label_col, view->font,
1978	            view->scale, view->pump_dirty_n,
1979	            view->pump_dirty_x1, view->pump_dirty_y1,
1980	            view->pump_dirty_x2, view->pump_dirty_y2, &label_drawn);
1981	        VMAP_PERF_T1(label);
1982	        VMAP_PERF_NB(n_labels, view->label_col.count);
1983	    }
1984	
1985	#if VMAP_TRACK_ENABLE
1986	    if (view->track) {
1987	        if (labels_drawn && canvas.clip_n > 0u) {
1988	            int32_t x1 = label_drawn.x1;
1989	            int32_t y1 = label_drawn.y1;
1990	            int32_t x2 = label_drawn.x2 + 1;
1991	            int32_t y2 = label_drawn.y2 + 1;
1992	            uint8_t i;
1993	
1994	            /*
1995	             * New labels may be outside the tile dirty edge. Expand the REC
1996	             * clip to their union so track ink is restored above those words.
1997	             */
1998	            for (i = 0; i < canvas.clip_n; i++) {
1999	                if (canvas.clip_x1[i] < x1) {
2000	                    x1 = canvas.clip_x1[i];
2001	                }
2002	                if (canvas.clip_y1[i] < y1) {
2003	                    y1 = canvas.clip_y1[i];
2004	                }
2005	                if (canvas.clip_x2[i] > x2) {
2006	                    x2 = canvas.clip_x2[i];
2007	                }
2008	                if (canvas.clip_y2[i] > y2) {
2009	                    y2 = canvas.clip_y2[i];
2010	                }
2011	            }
2012	            vmap_render_clip_reset(&canvas);
2013	            vmap_render_clip_add(&canvas, x1, y1, x2, y2);
2014	        }
2015	        VMAP_PERF_T0();
2016	        vmap_track_paint_to_canvas(view->track, &canvas);
2017	        VMAP_PERF_T1P(VMAP_PERF_TRACK_SLOT());
2018	    }
2019	#endif
2020	}
