2022	void vmap_view_stamp_nav_then_track(vmap_view_t * view)
2023	{
2024	    stamp_overlays(view, false);
2025	    if (view && view->canvas) {
2026	        lv_obj_invalidate(view->canvas);
2027	    }
2028	    vmap_perf_stamp_end((uint32_t)(view ? view->zoom : 0));
