2031	static void render_finish(vmap_view_t * view)
2032	{
2033	    stamp_overlays(view, true);
2034	    /* 必须在 dvfs_map_busy(false) 之前：MAP hold 期间 HCLK 才是被钉住的那档。
2035	     * 也要在 pump_dirty_n 被清零之前取，脏区条数是判"全量重画 / scroll 补边"的依据。 */
2036	    vmap_perf_frame_end((uint32_t)view->zoom, (uint32_t)view->pump_dirty_n);
2037	
2038	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
2039	    bicycle_inval_probe_tag("vmap_render");
2040	#endif
2041	    view->render_rev++;
2042	    view->paint_zoom = view->zoom;
2043	    view->paint_scale = view->scale;
2044	    view->pump_phase = 0;
2045	    view->pump_need_region = 0;
2046	    view->pump_dirty_n = 0;
2047	    lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
2048	
2049	    if (view->restamp_pending && !myvendor_mtp_lfs_quiesce()) {
2050	        view->restamp_pending = 0;
2051	        lv_obj_invalidate(view->canvas);
2052	        render_begin(view, false, false);
2053	        return;
2054	    }
2055	    dvfs_map_busy(false);
2056	    lv_obj_invalidate(view->canvas);
2057	    vmap_view_bring_arrow_to_front(view);
2058	}
