2094	bool vmap_view_render_pump(vmap_view_t * view, unsigned max_tiles)
2095	{
2096	    unsigned n;
2097	    uint32_t t0;
2098	
2099	    if (!view || !view->canvas || !view->cbuf || myvendor_mtp_lfs_quiesce()) {
2100	        return true;
2101	    }
2102	
2103	    if (view->pump_phase == 0) {
2104	        /* 没有帧在飞 ⇒ 泵本来就不该被调用（帧结束后定时器自己暂停）。
2105	         * **基准必须作废**，否则下一帧的第一拍会把"这一整段空闲"算成"UI 线程被占住"
2106	         * —— 第一版就是这么误报的：`SLOW pump gap 9471ms` / `2228ms` 其实都是
2107	         * "这段时间没渲染"（同期 BLE 每 10 秒的心跳照打，证明系统是活的）。 */
2108	        s_pf_last_pump_cyc = 0u;
2109	        return true;
2110	    }
2111	
2112	    if (max_tiles == 0) {
2113	        max_tiles = VMAP_RENDER_PUMP_MAX_TILES;
2114	    }
2115	
2116	    t0 = lv_tick_get();
2117	    myvendor_watchdog_ui_beat();
2118	    /* 单拍间隔超长 ⇒ **无条件** WARNING（正常帧不受影响）。只在这一帧确实在飞时量，
2119	     * 所以"没渲染的空闲"不会被算进来；而帧内一次 2 秒以上的拍间隔就只能是系统级
2120	     * 停顿（现场两次 WDT 饥饿复位都伴随 1.6~12 秒的这类间隔，且当时 [vperf] 正被
2121	     * 降到 debug、整场不可诊断）。 */
2122	    {
2123	        const uint32_t now_cyc = vmap_perf_cyc();
2124	
2125	        if (s_pf_last_pump_cyc != 0u && now_cyc - s_pf_last_pump_cyc
2126	            > VMAP_PERF_SLOW_GAP_MS * 240u * 1000u) {
2127	            syslog(LOG_WARNING,
2128	                "[vperf] SLOW pump gap %ums (>%ums) —— 帧内拍间隔异常，UI 线程被占住；若同时 WDT 停喂即饥饿族",
2129	                (unsigned)((now_cyc - s_pf_last_pump_cyc) / 240000u),
2130	                (unsigned)VMAP_PERF_SLOW_GAP_MS);
2131	            vmap_perf_dump_runnable();
2132	        }
2133	        s_pf_last_pump_cyc = now_cyc;
2134	    }
2135	
2136	    for (n = 0; n < max_tiles && view->pump_phase != 0; n++) {
2137	        if (n > 0 && lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2138	            break;
2139	        }
2140	        if (!render_next_tile(view)) {
2141	            render_finish(view);
2142	            break;
2143	        }
2144	        if (lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2145	            break;
2146	        }
2147	    }
2148	
2149	    return view->pump_phase == 0;
2150	}
