2171	/**
2172	 * @brief 用纯色清画布。
2173	 * @param c 画布。
2174	 * @param color RGB565。
2175	 */
2176	void vmap_render_clear(vmap_canvas_t * c, uint16_t color)
2177	{
2178	    vmap_blit_surface_t surf;
2179	
2180	    if (!c || !c->buf) {
2181	        return;
2182	    }
2183	
2184	    /* 先问搬运后端（走 EPIC 时是一整块矩形一条命令）；它不可用或没通过自检
2185	     * 时，同一个调用会把 CPU 版本做完 —— 见 vmap_blit.h。 */
2186	    render_surface(c, &surf);
2187	    vmap_blit_fill(render_blit(), &surf, 0, 0, c->w, c->h, color);
2188	}
2189	
2190	/*
2191	 * 这里原有一个 `render_fill_span(row, x0, x1, color)`（成对写的一行填充）。
2192	 * scroll 改成"矩形 + 两条边"之后它没有调用者了 —— 补边现在走
2193	 * `vmap_blit_fill()`，CPU 那支的成对写等价物在 `vmap_blit.c` 的 `cpu_fill()`。
2194	 */
2195	
2196	void vmap_render_scroll(vmap_canvas_t * c, int32_t dx, int32_t dy, uint16_t fill)
2197	{
2198	    vmap_blit_surface_t surf;
2199	    vmap_blit_t * blit;
2200	    int32_t copy_w;
2201	    int32_t copy_h;
2202	    int32_t x0;
2203	    int32_t y0;
2204	
2205	    if (!c || !c->buf) {
2206	        return;
2207	    }
2208	
2209	    if (dx == 0 && dy == 0) {
2210	        return;
2211	    }
2212	
2213	    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
2214	        vmap_render_clear(c, fill);
2215	        return;
2216	    }
2217	
2218	    /*
2219	     * 原来这条是逐行 memmove + 逐行补边；现在拆成**一块矩形 + 两条边**，
2220	     * 这样整块矩形才有机会落到 EPIC 上（一条命令 vs 472 次函数调用）。
2221	     * 逐行版的代价是实打实的：使用过程一帧的 `cyc_begin` 里 92% 就是它
2222	     * （见 `[vperf] frame ... scr=`），单帧 164 ms。
2223	     *
2224	     * 语义与逐行版逐位相同：
2225	     *   拷贝区 = 目的 (x0,y0) ← 源 (x0+dx, y0+dy)，尺寸 (w−|dx|, h−|dy|)；
2226	     *   横向露出的 |dx| 列只覆盖**拷贝区那几行**，纵向露出的 |dy| 行整宽铺满。
2227	     * 次序必须是**先拷贝后填充**：露出的边落在源矩形的范围内（横向边在
2228	     * y 属于拷贝区时、纵向边在 x 属于拷贝区时），先填会把还没读的源像素盖掉。
2229	     * 逐行版之所以没这个问题，是因为它在同一行里也是先 memmove 后补边、
2230	     * 且行的方向按 dy 的符号选过（跨行的重叠只有那个方向是安全的）。
2231	     */
2232	    copy_w = c->w - (dx >= 0 ? dx : -dx);
2233	    copy_h = c->h - (dy >= 0 ? dy : -dy);
2234	    x0 = (dx > 0) ? 0 : -dx;
2235	    y0 = (dy > 0) ? 0 : -dy;
2236	
2237	    render_surface(c, &surf);
2238	    blit = render_blit();
2239	
2240	    (void)vmap_blit_copy(blit, &surf, x0, y0, &surf, x0 + dx, y0 + dy,
2241	        copy_w, copy_h);
2242	
2243	    if (dx > 0) {
2244	        (void)vmap_blit_fill(blit, &surf, c->w - dx, y0, dx, copy_h, fill);
2245	    } else if (dx < 0) {
2246	        (void)vmap_blit_fill(blit, &surf, 0, y0, -dx, copy_h, fill);
2247	    }
2248	
2249	    if (dy > 0) {
2250	        (void)vmap_blit_fill(blit, &surf, 0, c->h - dy, c->w, dy, fill);
2251	    } else if (dy < 0) {
2252	        (void)vmap_blit_fill(blit, &surf, 0, 0, c->w, -dy, fill);
2253	    }
2254	}
