2256	static void fill_rect(vmap_canvas_t * c, int32_t x1, int32_t y1, int32_t x2,
2257	    int32_t y2, uint16_t color)
2258	{
2259	    int32_t y;
2260	
2261	    if (!c || x1 >= x2 || y1 >= y2) {
2262	        return;
2263	    }
2264	    if (x1 < 0) {
2265	        x1 = 0;
2266	    }
2267	    if (y1 < 0) {
2268	        y1 = 0;
2269	    }
2270	    if (x2 > c->w) {
2271	        x2 = c->w;
2272	    }
2273	    if (y2 > c->h) {
2274	        y2 = c->h;
2275	    }
2276	    if (x1 >= x2 || y1 >= y2) {
2277	        return;
2278	    }
2279	
2280	    for (y = y1; y < y2; y++) {
2281	        blend_span(c, x1, x2 - 1, y, color);
2282	    }
2283	}
