61	/**
62	 * @brief vmap geo point to seg m。
63	 */
64	double vmap_geo_point_to_seg_m(double px, double py,
65	    double ax, double ay, double bx, double by, double * t_out)
66	{
67	    const double seg_m = vmap_geo_haversine_m(ax, ay, bx, by);
68	    float brg = vmap_geo_bearing_deg(ax, ay, bx, by);
69	    float brg_p = vmap_geo_bearing_deg(ax, ay, px, py);
70	    const double ap_m = vmap_geo_haversine_m(ax, ay, px, py);
71	    double t = 0.0;
72	
73	    if (seg_m < 0.5) {
74	        if (t_out) {
75	            *t_out = 0.0;
76	        }
77	        return ap_m;
78	    }
79	
80	    {
81	        const double along = ap_m * cos((brg_p - brg) * M_PI / 180.0);
82	
83	        t = along / seg_m;
84	        if (t < 0.0) {
85	            t = 0.0;
86	        } else if (t > 1.0) {
87	            t = 1.0;
88	        }
89	    }
90	
91	    if (t_out) {
92	        *t_out = t;
93	    }
94	
95	    {
96	        const double mid_lon = ax + (bx - ax) * t;
97	        const double mid_lat = ay + (by - ay) * t;
98	
99	        return vmap_geo_haversine_m(px, py, mid_lon, mid_lat);
100	    }
101	}
