103	/**
104	 * @brief vmap geo project polyline m。
105	 */
106	double vmap_geo_project_polyline_m(const double * lons, const double * lats,
107	    uint32_t n, double lon, double lat, uint32_t * seg_index, double * t_on_seg)
108	{
109	    double best_d = 1e18;
110	    uint32_t best_i = 0;
111	    double best_t = 0.0;
112	
113	    if (!lons || !lats || n < 2) {
114	        if (seg_index) {
115	            *seg_index = 0;
116	        }
117	        if (t_on_seg) {
118	            *t_on_seg = 0.0;
119	        }
120	        return 1e18;
121	    }
122	
123	    for (uint32_t i = 0; i + 1 < n; i++) {
124	        double t = 0.0;
125	        const double d = vmap_geo_point_to_seg_m(lon, lat,
126	            lons[i], lats[i], lons[i + 1], lats[i + 1], &t);
127	
128	        if (d < best_d) {
129	            best_d = d;
130	            best_i = i;
131	            best_t = t;
132	        }
133	    }
134	
135	    if (seg_index) {
136	        *seg_index = best_i;
137	    }
138	    if (t_on_seg) {
139	        *t_on_seg = best_t;
140	    }
141	    return best_d;
142	}
