666	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
667	    int32_t canvas_h, double scale, int32_t ring,
668	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
669	{
670	    const int32_t tile_size = 256;
671	    double half_w = (canvas_w / 2.0) / scale;
672	    double half_h = (canvas_h / 2.0) / scale;
673	    double pad = (double)ring * tile_size;
674	    double left = (double)center_x - half_w - pad;
675	    double top = (double)center_y - half_h - pad;
676	    double right = (double)center_x + half_w + pad;
677	    double bottom = (double)center_y + half_h + pad;
678	
679	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
680	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
681	    *tx_max = (int32_t)(right / tile_size);
682	    *ty_max = (int32_t)(bottom / tile_size);
683	}
