685	static void vmap_view_apply_canvas_pos(vmap_view_t * view, double dx, double dy)
686	{
687	    lv_coord_t px;
688	    lv_coord_t py;
689	
690	    if (!view || !view->canvas) {
691	        return;
692	    }
693	
694	    px = (lv_coord_t)lround(dx);
695	    py = (lv_coord_t)lround(dy);
696	
697	    if (px == view->last_pan_px && py == view->last_pan_py) {
698	        return;
699	    }
700	
701	    /*
702	     * Moving a canvas invalidates the complete visible map. Coalesce sub-pixel
703	     * GNSS movement; the centered arrow still updates normally.
704	     */
705	    if (view->last_pan_px != INT32_MIN && view->last_pan_py != INT32_MIN
706	        && abs((int)px - view->last_pan_px) < VMAP_PAN_MIN_STEP_PX
707	        && abs((int)py - view->last_pan_py) < VMAP_PAN_MIN_STEP_PX) {
708	        return;
709	    }
710	
711	    view->pan_dx = (double)px;
712	    view->pan_dy = (double)py;
713	    view->last_pan_px = px;
714	    view->last_pan_py = py;
715	    view->map_rev++;
716	    vmap_label_collector_set_focus(&view->label_col,
717	        view->w / 2 + px, view->h / 2 + py);
718	#if defined(CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE) && CONFIG_MYVENDOR_BICYCLE_INVAL_PROBE
719	    bicycle_inval_probe_tag("vmap_pan");
720	#endif
721	    /* lv_obj_set_pos already invalidates old + new areas; do not inval again. */
722	    /* y_bias 只加在屏幕位置上：pan_dy 与投影原点都不动，于是偏置与跟车/rebase
723	     * 的数学完全解耦（偏置变化既不触发重算，也不改变 rebase 时机）。 */
724	    lv_obj_set_pos(view->canvas,
725	        (lv_coord_t)(-view->margin - px),
726	        (lv_coord_t)(-view->margin - py + view->y_bias));
727	}
