729	static bool vmap_view_geo_to_viewport_impl(const vmap_view_t * view, double lon, double lat,
730	    int32_t * out_x, int32_t * out_y, bool check_visible)
731	{
732	    int base_x = 0;
733	    int base_y = 0;
734	    int geo_x = 0;
735	    int geo_y = 0;
736	    double cx;
737	    double cy;
738	    int32_t sx;
739	    int32_t sy;
740	    const int32_t pad = 24;
741	
742	    if (!view) {
743	        return false;
744	    }
745	
746	    vmap_latlong_to_pixel(view->render_lat, view->render_lon, view->zoom, &base_x, &base_y);
747	    vmap_latlong_to_pixel(lat, lon, view->zoom, &geo_x, &geo_y);
748	
749	    cx = (geo_x - base_x) * view->scale + (double)view->w / 2.0;
750	    cy = (geo_y - base_y) * view->scale + (double)view->h / 2.0;
751	    sx = (int32_t)lround(cx - (double)view->margin - view->pan_dx);
752	    sy = (int32_t)lround(cy - (double)view->margin - view->pan_dy);
753	
754	    if (out_x) {
755	        *out_x = sx;
756	    }
757	    if (out_y) {
758	        *out_y = sy;
759	    }
760	
761	    if (!check_visible) {
762	        return true;
763	    }
764	
765	    return sx >= -pad && sy >= -pad
766	        && sx <= view->view_w + pad && sy <= view->view_h + pad;
767	}
