static void blit_clip(const vmap_blit_surface_t * s, int32_t * x, int32_t * y,
    int32_t * w, int32_t * h)
{
    if (*x < 0) { *w += *x; *x = 0; }
    if (*y < 0) { *h += *y; *y = 0; }
    if (*x + *w > s->w) { *w = s->w - *x; }
    if (*y + *h > s->h) { *h = s->h - *y; }
    if (*w < 0) { *w = 0; }
    if (*h < 0) { *h = 0; }
}

bool vmap_blit_fill(vmap_blit_t * b, const vmap_blit_surface_t * dst,
    int32_t x, int32_t y, int32_t w, int32_t h, uint16_t color)
{
    (void)b;
    blit_clip(dst, &x, &y, &w, &h);
    for (int32_t j = 0; j < h; j++) {
        uint16_t * row = (uint16_t *)((uint8_t *)dst->buf + (size_t)(y + j) * dst->stride);
        for (int32_t i = 0; i < w; i++) { row[x + i] = color; }
    }
    return false;
}

bool vmap_blit_copy(vmap_blit_t * b, const vmap_blit_surface_t * dst,
    int32_t dx, int32_t dy, const vmap_blit_surface_t * src,
    int32_t sx, int32_t sy, int32_t w, int32_t h)
{
    (void)b; (void)dst; (void)dx; (void)dy; (void)src; (void)sx; (void)sy; (void)w; (void)h;
    return false;
}

/* ---- VTIL 记录序列化 ---- */
static uint8_t g_data[1 << 20];
static size_t g_len;
static uint16_t g_count;

static void put_u8(uint8_t v) { g_data[g_len++] = v; }
static void put_u16(uint16_t v) { g_data[g_len++] = (uint8_t)(v & 0xFF); g_data[g_len++] = (uint8_t)(v >> 8); }

static void add_feature(uint8_t attr, uint8_t flags, uint16_t npts,
    const uint8_t * name, uint8_t name_len)
{
    put_u8(attr);
    put_u8(flags);
    put_u16(npts);
    for (uint16_t i = 0; i < npts; i++) {
        put_u16((uint16_t)((i * 977u + attr * 131u) % 4090u));
        put_u16((uint16_t)((i * 613u + attr * 271u) % 4090u));
    }
    if (flags & VMAP_FLAG_NAMED) {
        put_u8(name_len);
        for (uint8_t i = 0; i < name_len; i++) { put_u8(name ? name[i] : (uint8_t)('a' + i)); }

