void vmap_view_set_heading(vmap_view_t * view, float heading_deg)
{
    double d = (double)heading_deg;
    int32_t target;
    int32_t delta;

    if (!view || !view->heading_up || !view->canvas) {
        return;
    }
    if (!(d >= 0.0) || !(d < 360.0)) {
        return;   /* NaN / 越界：宁可不转 */
    }

    if (!view->heading_valid) {
        view->heading_deg = d;
        view->heading_valid = true;
