/* ===== 帧率/刷新统计（诊断用，LV_EVENT_REFR_START/READY） ===== */
static struct {
    uint32_t t_start;
    uint32_t n;
    uint32_t sum_ms;
    uint32_t max_ms;
    uint32_t win_ms;
} s_fps;
static bool s_fps_hooked;
static vmap_view_t * s_fps_view;   /* 只为取 canvas/display */

static void vmap_fps_event_cb(lv_event_t * e)
{
    lv_event_code_t code = lv_event_get_code(e);
    uint32_t now = lv_tick_get();

    if (code == LV_EVENT_REFR_START) {
        s_fps.t_start = now;
    } else if (code == LV_EVENT_REFR_READY) {
        uint32_t dt = lv_tick_elaps(s_fps.t_start);
        s_fps.n++;
        s_fps.sum_ms += dt;
        if (dt > s_fps.max_ms) s_fps.max_ms = dt;
        if (s_fps.win_ms == 0) s_fps.win_ms = now;
        if (lv_tick_elaps(s_fps.win_ms) >= 2000) {
            if (s_fps.n > 0) {
                syslog(LOG_NOTICE, "[mapfps] n=%u avg=%ums max=%ums win=%ums hz_x10=%u",
                    ...);
            }
            reset;
        }
    }
}
