/* ===== 诊断：屏幕实际重绘帧率（LV_EVENT_RENDER_START/READY） ===== */
static struct {
    uint32_t t0;
    uint32_t n;
    uint32_t sum;
    uint32_t max;
    uint32_t win;
} s_fps;
static bool s_fps_hooked;

static void vmap_fps_cb(lv_event_t * e)
{
    const lv_event_code_t code = lv_event_get_code(e);
    uint32_t now = lv_tick_get();

    if (code == LV_EVENT_RENDER_START) {
        s_fps.t0 = now;
        return;
    }
    if (code != LV_EVENT_RENDER_READY) {
        return;
    }
    {
        uint32_t dt = lv_tick_elaps(s_fps.t0);
        if (s_fps.win == 0) s_fps.win = now;
        s_fps.n++;
        s_fps.sum += dt;
        if (dt > s_fps.max) s_fps.max = dt;
        if (lv_tick_elaps(s_fps.win) >= 2000u) {
            uint32_t win = lv_tick_elaps(s_fps.win);
            if (s_fps.n > 0) {
                syslog(LOG_NOTICE,
                    "[mapfps] n=%u fps=%u.%u avg=%ums max=%ums win=%ums",
                    (unsigned)s_fps.n,
                    (unsigned)(s_fps.n * 1000u / win),
                    (unsigned)((s_fps.n * 10000u / win) % 10u),
                    (unsigned)(s_fps.sum / s_fps.n),
                    (unsigned)s_fps.max,
                    (unsigned)win);
            }
            s_fps.n = 0; s_fps.sum = 0; s_fps.max = 0; s_fps.win = now;
        }
    }
}
