/**
 * @brief 把本帧收集到的路名按"旋转后的屏幕位置"摆成正立文本对象。
 * @details 文本不烘进画布（否则会跟着地图转成斜字）；位置 = R 中心 +
 *          R(θ)·(画布点 - 骑手点)，再换算到 map_area 坐标。同名只留一条。
 */
static void vmap_rot_labels_update(vmap_view_t * view, int32_t pivot_x,
    int32_t pivot_y)
{
    const double th = (double)view->rot10 * 0.1 * M_PI / 180.0;
    const double c = cos(th);
    const double s = sin(th);
    const char * taken[VMAP_ROT_LABEL_MAX];
    int32_t i;
    int32_t n = 0;

    if (!view->rot_labels || view->font == NULL || view->label_col.count <= 0) {
        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
            lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
        }
        view->rot_label_n = 0;
        return;
    }

    for (i = 0; i < view->label_col.count && n < VMAP_ROT_LABEL_MAX; i++) {
        const vmap_label_cand_t * it = &view->label_col.items[i];
        const double dx = (double)it->x - (double)pivot_x;
        const double dy = (double)it->y - (double)pivot_y;
        const int32_t rx = (int32_t)lround((double)view->rw / 2.0
            + (c * dx - s * dy));
        const int32_t ry = (int32_t)lround((double)view->rh / 2.0
            + (s * dx + c * dy));
        const int32_t sx = rx - view->r_margin;
        const int32_t sy = ry - view->r_margin + view->y_bias;
        lv_obj_t * l;
        int32_t k;
        bool dup = false;

        if (it->name[0] == '\0') {
            continue;
        }
        /* 只留视口附近（留点余量，边缘字不会突然跳出来）。 */
        if (sx < -24 || sy < -24 || sx > view->view_w + 24
            || sy > view->view_h + 24) {
            continue;
        }
        for (k = 0; k < n; k++) {
            if (strcmp(taken[k], it->name) == 0) {
                dup = true;
                break;
            }
        }
        if (dup) {
            continue;
        }

        l = view->rot_label[n];
        lv_label_set_text(l, it->name);
        lv_obj_set_style_text_color(l, lv_color_hex(vmap_rot_label_color(it->kind)), 0);
        lv_obj_update_layout(l);
        view->rlx[n] = sx - lv_obj_get_width(l) / 2;
        view->rly[n] = sy - lv_obj_get_height(l) / 2;
        lv_obj_set_pos(l, view->rlx[n], view->rly[n]);
        lv_obj_clear_flag(l, LV_OBJ_FLAG_HIDDEN);
        taken[n] = it->name;
        n++;
    }

    for (; n < VMAP_ROT_LABEL_MAX; n++) {
        lv_obj_add_flag(view->rot_label[n], LV_OBJ_FLAG_HIDDEN);
    }
    view->rot_label_n = (uint8_t)n;
