double vmap_geo_point_to_seg_m(double px, double py, double ax, double ay,
    double bx, double by, double *t_out)
{
    /* 等距圆柱局部平面：一个 cos（带缓存）+ 纯乘加。
     * 逐段用 haversine+bearing 时，FP64 超越函数在这颗 FP32 核上是软件实现，
     * 2000 段的路线投影一次要 195 ms（实测 2026-10-28）。 */
    const double kx = vmap_geo_kx_for_lat(ay);
    const double ky = VMAP_GEO_M_PER_DEG_LAT;
    const double vx = (bx - ax) * kx;
    const double vy = (by - ay) * ky;
    const double wx = (px - ax) * kx;
    const double wy = (py - ay) * ky;
    const double seg2 = vx * vx + vy * vy;
    double t = 0.0;

    if (seg2 > 1e-6) {
        t = (wx * vx + wy * vy) / seg2;
        if (t < 0.0) t = 0.0; else if (t > 1.0) t = 1.0;
