                                EPIC_LayerConfigTypeDef * output_layer)
{
    EPIC_HandleTypeDef * epic = lv_epic_get_handle();

    if(epic_prepare_start(epic, NULL) != HAL_OK) {
        return HAL_ERROR;
    }

    lv_epic_flush_layers_cache(input_layers, input_layer_cnt, output_layer);

