            lv_epic_osa_set_idle();
            return ret;
        }

        if(!epic_sem_ready) {
            (void)nxsem_init(&epic_done_sem, 0, 0);
            epic_sem_ready = true;
        }

        while(nxsem_trywait(&epic_done_sem) == 0) {
            /* drain stale posts */
        }
        epic_done_flag = false;

        epic->XferCpltCallback = epic_cplt_cb;
        HAL_StatusTypeDef ret = HAL_EPIC_BlendStartEx_IT(epic, input_layers, input_layer_cnt,
                                                         output_layer);
        if(ret != HAL_OK) {
            epic->XferCpltCallback = NULL;
            lv_epic_osa_set_idle();
            return ret;
        }

        for(int waited = 0; waited < 4 && !epic_done_flag; waited++) {
